const zone = 'America/Sao_Paulo';
const hoje = DateTime.now().setZone(zone);
let since, until;
if ($execution.mode !== 'production') {
  since = hoje.minus({ days: 30 }).toFormat('yyyy-LL-dd');
  until = hoje.minus({ days: 1 }).toFormat('yyyy-LL-dd');
} else {
  const ontem = hoje.minus({ days: 1 }).toFormat('yyyy-LL-dd');
  since = ontem; until = ontem;
}
return [{ json: { since: since, until: until } }];

const fmt = (n) => {
  const v = Number(n);
  if (!isFinite(v)) return '';
  return (Math.round(v * 100) / 100).toFixed(2).replace('.', ',');
};
const inteiro = (n) => String(parseInt(n || 0, 10) || 0);
const dataBr = (iso) => { const p = String(iso || '').split('-'); return p.length === 3 ? p[2] + '/' + p[1] + '/' + p[0] : ''; };
const LEADS_T = ['lead','onsite_conversion.lead_grouped','leadgen_grouped','offsite_conversion.fb_pixel_lead','onsite_web_lead'];
const COMPRAS_T = ['omni_purchase','purchase','offsite_conversion.fb_pixel_purchase','onsite_web_purchase'];
const pega = (arr, tipos) => {
  if (!Array.isArray(arr)) return 0;
  for (const t of tipos) {
    const hit = arr.find(a => a.action_type === t);
    if (hit) return Number(hit.value) || 0;
  }
  return 0;
};
const registros = [];
for (const item of $input.all()) {
  const corpo = item.json || {};
  const lista = Array.isArray(corpo.data) ? corpo.data : [];
  for (const r of lista) registros.push(r);
}
const linhas = [];
for (const r of registros) {
  const gasto = Number(r.spend) || 0;
  const leads = pega(r.actions, LEADS_T);
  const compras = pega(r.actions, COMPRAS_T);
  const valor = pega(r.action_values, COMPRAS_T);
  linhas.push({ json: {
    'Data': dataBr(r.date_start),
    'Plataforma': 'Meta Ads',
    'Campanha': r.campaign_name || '',
    'Campanha_ID': r.campaign_id || '',
    'Gasto': fmt(gasto),
    'Impressoes': inteiro(r.impressions),
    'Cliques': inteiro(r.clicks),
    'CPM': fmt(r.cpm),
    'CPC': fmt(r.cpc),
    'CTR': fmt(r.ctr),
    'Leads': inteiro(leads),
    'Compras': inteiro(compras),
    'Valor_Compras': fmt(valor),
    'CPL': leads > 0 ? fmt(gasto / leads) : '',
    'CPA': compras > 0 ? fmt(gasto / compras) : '',
    'ROAS': gasto > 0 && valor > 0 ? fmt(valor / gasto) : '',
    '_d': r.date_start,
    '_gasto': gasto,
    '_imp': parseInt(r.impressions || 0, 10) || 0,
    '_cli': parseInt(r.clicks || 0, 10) || 0,
    '_cpm': Number(r.cpm) || 0,
    '_cpc': Number(r.cpc) || 0,
    '_ctr': Number(r.ctr) || 0,
    '_leads': leads,
    '_compras': compras,
    '_valor': valor
  } });
}
return linhas;

